package com.dra.contracts.dto;

import com.dra.contracts.model.Depth;

import java.io.Serializable;
import java.util.List;

/** Workflow input. taskId is generated by the API before starting the workflow. */
public record ResearchRequest(
        String taskId,
        String question,
        Depth depth,
        int deadlineMinutes,
        long budgetTokens,
        long budgetCostMicros,
        String language,
        List<String> allowedDomains,
        List<String> excludedDomains) implements Serializable {

    public ResearchRequest {
        if (taskId == null || taskId.isBlank()) {
            throw new IllegalArgumentException("taskId is required");
        }
        if (question == null || question.isBlank()) {
            throw new IllegalArgumentException("question is required");
        }
        depth = depth == null ? Depth.STANDARD : depth;
        deadlineMinutes = deadlineMinutes <= 0 ? depth.defaultDeadlineMinutes() : deadlineMinutes;
        budgetTokens = budgetTokens <= 0 ? depth.defaultBudgetTokens() : budgetTokens;
        budgetCostMicros = Math.max(0, budgetCostMicros);
        language = (language == null || language.isBlank()) ? "auto" : language;
        allowedDomains = allowedDomains == null ? List.of() : List.copyOf(allowedDomains);
        excludedDomains = excludedDomains == null ? List.of() : List.copyOf(excludedDomains);
    }

    public static ResearchRequest of(String taskId, String question, Depth depth) {
        return new ResearchRequest(taskId, question, depth, 0, 0, 0, "auto", List.of(), List.of());
    }
}
